WITH base AS (SELECT *, COALESCE(stock_qty, 0) AS stock_qty_filled, COALESCE(brand, 'N/A') AS resolved_brand FROM products WHERE price < 1150), with_dims AS (SELECT e.*, p.rating FROM base e LEFT JOIN suppliers p ON e.supplier_id = p.id), filtered AS (SELECT id, product_name, category, price, stock_qty, tags, supplier_id, stock_qty_filled, resolved_brand, rating, LOWER(product_name) AS product_name_lower FROM with_dims WHERE launch_date > DATE '2023-06-18'), not_flagged AS (SELECT s.* FROM filtered s WHERE NOT EXISTS (SELECT 1 FROM store_sales ch WHERE ch.product_id = s.id AND ch.store_id IN (1, 4))), metrics AS (SELECT *, DENSE_RANK() OVER (PARTITION BY supplier_id, category ORDER BY rating) AS rating_dense_rank, PERCENT_RANK() OVER (PARTITION BY category ORDER BY rating DESC NULLS FIRST) AS rating_percent_rank FROM not_flagged), eligible AS (SELECT s.* FROM metrics s WHERE EXISTS (SELECT 1 FROM order_items c WHERE c.product_id = s.id AND c.quantity BETWEEN 4 AND 8)) SELECT category, supplier_id, COUNT(*) AS cnt, COUNT(DISTINCT category) AS distinct_categories, COUNT_IF(category = 'Home') AS home_events, SIZE(COLLECT_SET(category)) AS num_categories, PERCENT_RANK() OVER (PARTITION BY category ORDER BY COUNT(*) DESC) AS cnt_percent_rank FROM eligible GROUP BY 1, 2 ORDER BY num_categories DESC
